const rows = [
  { cat: 'shoes', price: 129 }, { cat: 'shoes', price: 139 },
  { cat: 'apparel', price: 59 }, { cat: 'shoes', price: 100 },
];
const groups = {};
for (const r of rows) groups[r.cat] = (groups[r.cat] || 0) + r.price;
const grand = Object.values(groups).reduce((s, v) => s + v, 0);
const raw = rows.reduce((s, r) => s + r.price, 0);
console.log('shoes=' + groups.shoes + ' apparel=' + groups.apparel);
console.log('reconciled=' + (grand === raw));
console.log('grand=' + grand);

